const MAX_IDS = 5;

export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description:
        'Look up multiple users by id. Returns one line per requested id in request order, marking missing users without failing the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: MAX_IDS,
          },
        },
        required: ['user_ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  validateArguments(args);

  const userIds = args.user_ids;
  const lines = userIds.map((id) => {
    const user = users[id];
    return user ? `${id}: ${user.name}` : `${id}: not found`;
  });

  return {
    content: [{ type: 'text', text: lines.join('\n') }],
  };
}

function validateArguments(args) {
  if (
    args === null ||
    typeof args !== 'object' ||
    Array.isArray(args)
  ) {
    throw new Error('Arguments must be an object');
  }

  const keys = Object.keys(args);
  if (keys.length !== 1 || keys[0] !== 'user_ids') {
    throw new Error('Unexpected arguments; only "user_ids" is allowed');
  }

  const { user_ids } = args;
  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }
  if (user_ids.length === 0) {
    throw new Error('user_ids must be a non-empty array');
  }
  if (user_ids.length > MAX_IDS) {
    throw new Error(`user_ids may contain at most ${MAX_IDS} entries`);
  }

  const seen = new Set();
  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('Every entry in user_ids must be a string');
    }
    if (seen.has(id)) {
      throw new Error(`Duplicate user id: ${id}`);
    }
    seen.add(id);
  }
}
"}

